def flatten(nested):
    for item in nested:
        if isinstance(item, list):
            yield from flatten(item)   # delegate to the sub-generator
        else:
            yield item

print(list(flatten([1, [2, [3, []]], 4])))  # [1, 2, 3, 4]

def running_mean():
    total = count = 0
    mean = None
    while True:
        value = yield mean     # send(v) makes this expression v
        total += value
        count += 1
        mean = total / count

avg = running_mean()
next(avg)                              # prime: run to the first yield
print(avg.send(10), avg.send(20))      # 10.0 15.0

from itertools import islice

def read_numbers(lines):
    for line in lines:
        if line.strip():
            yield int(line)

lines = (f'{i}\n' for i in range(10**9))   # a billion-line 'file'
evens = (n for n in read_numbers(lines) if n % 2 == 0)
squares = (n * n for n in evens)
print(list(islice(squares, 3)))   # [0, 4, 16]: only 5 lines were read

xs = [1, 2, 2, 3]
for x in xs:
    if x == 2:
        xs.remove(x)      # shifts items left; the loop skips one
print(xs)                 # [1, 2, 3]

xs = [1, 2, 2, 3]
xs = [x for x in xs if x != 2]   # build a new list
print(xs)                        # [1, 3]

stock = {'a': 0, 'b': 3}
for key in list(stock):          # loop over a snapshot of the keys
    if stock[key] == 0:
        del stock[key]
print(stock)                     # {'b': 3}

