from itertools import islice, count

def collatz(n):
    while True:
        yield n
        n = n // 2 if n % 2 == 0 else 3 * n + 1

def first_terms(start, k):
    return list(islice(collatz(start), k))   # bound the infinite generator

print(first_terms(6, 5))   # [6, 3, 10, 5, 16]
print(next(n for n in count(1) if n * n > 50))   # 8: first match, then stop

