from collections import deque

_DONE = object()

def round_robin(iterables):
    queue = deque(iter(xs) for xs in iterables)
    while queue:
        it = queue.popleft()
        value = next(it, _DONE)
        if value is not _DONE:
            yield value
            queue.append(it)

def interleave(lists):
    return list(round_robin(lists))

